create extension if not exists pgcrypto;
create table organizations(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,plan text not null default 'starter',custom_domain text unique,branding jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table memberships(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations on delete cascade,user_id uuid not null references auth.users on delete cascade,role text not null default 'viewer',created_at timestamptz not null default now(),unique(organization_id,user_id));
create table products(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations on delete cascade,name text not null,slug text not null,description text not null default '',status text not null default 'draft',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,slug));
create table product_variants(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations on delete cascade,product_id uuid not null references products on delete cascade,sku text not null,price numeric(12,2) not null check(price>=0),stock integer not null default 0 check(stock>=0),attributes jsonb not null default '{}'::jsonb,unique(organization_id,sku));
create table inventory_movements(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations on delete cascade,variant_id uuid not null references product_variants on delete cascade,kind text not null,quantity integer not null,reference_type text,reference_id uuid,note text,created_at timestamptz not null default now());
create table orders(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations on delete cascade,order_number text not null,status text not null default 'pending',payment_status text not null default 'pending',customer_email text,total numeric(12,2) not null default 0,created_at timestamptz not null default now(),unique(organization_id,order_number));
create table order_items(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations on delete cascade,order_id uuid not null references orders on delete cascade,variant_id uuid references product_variants,product_name text not null,sku text not null,quantity integer not null check(quantity>0),unit_price numeric(12,2) not null check(unit_price>=0));
create index products_org_status_idx on products(organization_id,status);create index variants_product_idx on product_variants(product_id);create index inventory_org_variant_idx on inventory_movements(organization_id,variant_id,created_at desc);create index orders_org_created_idx on orders(organization_id,created_at desc);
alter table organizations enable row level security;alter table memberships enable row level security;alter table products enable row level security;alter table product_variants enable row level security;alter table inventory_movements enable row level security;alter table orders enable row level security;alter table order_items enable row level security;
create policy "members read own memberships" on memberships for select to authenticated using (user_id=(select auth.uid()));
create policy "members read organizations" on organizations for select to authenticated using (id in(select organization_id from memberships where user_id=(select auth.uid())));
create policy "members read products" on products for select to authenticated using (organization_id in(select organization_id from memberships where user_id=(select auth.uid())));
create policy "members read variants" on product_variants for select to authenticated using (organization_id in(select organization_id from memberships where user_id=(select auth.uid())));
create policy "members read inventory" on inventory_movements for select to authenticated using (organization_id in(select organization_id from memberships where user_id=(select auth.uid())));
create policy "members read orders" on orders for select to authenticated using (organization_id in(select organization_id from memberships where user_id=(select auth.uid())));
create policy "members read order items" on order_items for select to authenticated using (organization_id in(select organization_id from memberships where user_id=(select auth.uid())));
